queries.inputQueryString:
UNPIVOT ${food_table_compounds_prediction_average_points}
ON average_state_point, average_sleep_point, average_bloating_point, average_reflux_point, average_finger_point
INTO
    NAME state_name
    VALUE average_value;

select 'What can be in common in these compounds that make me sleepy? ' ||
       string_agg(compound || '-' || round(average_sleep_point, 2)::text, ', ' order by average_sleep_point desc) as prompt
from ${food_table_compounds_prediction_average_points}

select 'What can be in common in these compounds that affect my mental state? ' ||
       string_agg(compound || '-' || round(average_state_point, 2)::text, ', ' order by average_state_point desc) as prompt
from ${food_table_compounds_prediction_average_points}

select 'What can be in common in these compounds that cause me bloating? ' ||
       string_agg(compound || '-' || round(average_bloating_point, 2)::text, ', ' order by average_bloating_point desc) as prompt
from ${food_table_compounds_prediction_average_points}

select 'What can be in common in these compounds that cause me reflux? ' ||
       string_agg(compound || '-' || round(average_reflux_point, 2)::text, ', ' order by average_reflux_point desc) as prompt
from ${food_table_compounds_prediction_average_points}

select 'What can be in common in these compounds that cause my fingers to swell? ' ||
       string_agg(compound || '-' || round(average_finger_point, 2)::text, ', ' order by average_finger_point desc) as prompt
from ${food_table_compounds_prediction_average_points}
